     * @notice Pay order amount
     * @param boxId_ BlindBox ID
     * @param from_ Buyer address
     * @param amount_ Amount to pay
     * @param userId_ Buyer id
     * @dev Only callable by project contracts
     */
    function payOrderAmount(
        uint256 boxId_,
        address from_,
        uint256 amount_,
        bytes32 userId_
    ) external;

