// SPDX-License-Identifier: GPL-2.0-or-later
// OpenZeppelin Contracts (last updated v5.0.0) (token/ERC721/ERC721.sol)

pragma solidity ^0.8.24;

import {
    ERC2771Context
} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";

import {IBlindBox} from "@interfaces/sapphire/IBlindBox.sol";
import {BoxStatus} from "@interfaces/base/BoxStatus.sol";

import {ExchangeEvents} from "@interfaces/IExchange.sol";
import {Exchange01} from "./Exchange01.sol";
// import {SiweContext} from "@siwe/SiweContext.sol";

/**
 *  @notice Exchange02 contract
 *  Implement basic BlindBox trading functions, including Selling, Auctioning, Paid, Refunding, Completed
 *  @dev Inherits IExchange interface to ensure consistency between interface and implementation
 */

contract Exchange02 is Exchange01, ExchangeEvents, ERC2771Context {
    // =======================================================================================================

    struct ExchangeData {
        address _acceptedToken; // If address(0), then it means support settlementToken
        bytes32 _sellerId; // If address(0), then it means by minter sell
        bytes32 _buyerId;
        bytes32 _completerId;
        uint256 _refundRequestDeadline;
        uint256 _arbitrationDeadline;
        bool _refundPermit;
    }

    mapping(uint256 boxId => ExchangeData data) internal _boxExchangeData;

    // ========================================================================================================

    constructor(address addrManager_, address trustedForwarder_) Exchange01(addrManager_) ERC2771Context(trustedForwarder_) {}

    // ========================================================================================================
    //                                           Checker functions
    // ========================================================================================================

    /**
     * @notice Read box status
     * @param boxId_ Box ID
     * If the box status is Auctioning, and the deadline is over, then it is directly Paid.
     */
    // function _isStatus(uint256 boxId_, BoxStatus status_) internal view {
    //     if (BLIND_BOX.getStatus(boxId_) != status_) revert InvalidStatus();
    // }
    // Check the refund timestamp. Within the refund time,
    // you can apply for a refund (set to refunding mode),
    function _isInRequestRefundDeadline(
        uint256 boxId_
    ) internal view returns (bool) {
        if (_boxExchangeData[boxId_]._refundRequestDeadline < block.timestamp)
            return false;
        return true;
    }

    function _isInArbitrationDeadline(uint256 boxId_) internal view returns (bool) {
        if (_boxExchangeData[boxId_]._arbitrationDeadline < block.timestamp)
            return false;
        return true;
    }

    // ========================================================================================================
    //                                            Setter functions
    //========================================================================================================

    function _setBoxListedArgs(
        uint256 boxId_,
        address acceptedToken_,
        uint256 price_,
        BoxStatus status_,
        uint256 seconds_
    ) internal {
        IBlindBox BlindBox = BLIND_BOX;
        if (BlindBox.getStatus(boxId_) != BoxStatus.Storing)
            revert InvalidStatus();
        // erc2771 - _msgSender() is the real caller
        address sender = _msgSender();

        bytes32 userId = USER_MANAGER.getUserId(sender);
        address token = ADDR_MANAGER.settlementToken();

        if (userId != BlindBox.minterIdOf(boxId_)) {
            // others sell
            if (BlindBox.getDeadline(boxId_) >= block.timestamp) {
                revert DeadlineNotOver();
            }
            _boxExchangeData[boxId_]._sellerId = userId;

            // if the _sellerId is not the minter, they can't set the price
            price_ = 0;
        } else {
            if (
                acceptedToken_ != token && 
                ADDR_MANAGER.isTokenSupported(acceptedToken_)
            ) {

                _boxExchangeData[boxId_]._acceptedToken = acceptedToken_;
                token = acceptedToken_;
            }
        }

        BlindBox.setBasicData(
            boxId_,
            price_,
            status_,
            block.timestamp + seconds_
        );

        emit BoxListed(boxId_, userId, token);
    }

    function _setRefundRequestDeadline(
        uint256 boxId_,
        uint256 timestamp
    ) internal {
        uint256 deadline = timestamp + _refundRequestPeriod;
        _boxExchangeData[boxId_]._refundRequestDeadline = deadline;

        emit RequestDeadlineChanged(boxId_, deadline);
    }

    function _setRefundPermitTrue(uint256 boxId_) internal {
        _boxExchangeData[boxId_]._refundPermit = true;
        emit RefundPermitChanged(boxId_, true);
    }

    // ========================================================================================================
    //                                           Getter function
    // ========================================================================================================

    function _buyerIdOf(uint256 boxId_) internal view returns (bytes32) {
        return _boxExchangeData[boxId_]._buyerId;
    }

    function _sellerIdOf(uint256 boxId_) internal view returns (bytes32) {
        return _boxExchangeData[boxId_]._sellerId;
    }

    function _completerIdOf(uint256 boxId_) internal view returns (bytes32) {
        return _boxExchangeData[boxId_]._completerId;
    }

    function _refundPermit(uint256 boxId_) internal view returns (bool) {
        return _boxExchangeData[boxId_]._refundPermit;
    }

    /**
     * @notice Get supported token
     */
    function _acceptedToken(uint256 boxId_) internal view returns (address) {
        address token = _boxExchangeData[boxId_]._acceptedToken;
        if (token == address(0)) return ADDR_MANAGER.settlementToken();
        return token;
    }

    function _arbitrationDeadline(
        uint256 boxId_
    ) internal view returns (uint256) {
        return _boxExchangeData[boxId_]._arbitrationDeadline;
    }

    function _refundRequestDeadline(
        uint256 boxId_
    ) internal view returns (uint256) {
        return _boxExchangeData[boxId_]._refundRequestDeadline;
    }

    // -------------------------------------------------------------------
}

contracts/base/Exchange03.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later
// OpenZeppelin Contracts (last updated v5.0.0) (token/ERC721/ERC721.sol)

pragma solidity ^0.8.24;

import {IBlindBox} from "@interfaces/sapphire/IBlindBox.sol";
import {BoxStatus} from "@interfaces/base/BoxStatus.sol";

import {Exchange02} from "./Exchange02.sol";
import {Main} from "@interfaces/base/IContracts.sol";

/**
 *  @notice Exchange03 contract
 *  Implement basic blindBox trading functions, including Selling, Auctioning, Paid, Refunding, Completed
 *  @dev Inherits IExchange interface to ensure consistency between interface and implementation
 */

contract Exchange03 is Exchange02 {
    // ========================================================================================================

    constructor(address addrManager_, address trustForwarder_) Exchange02(addrManager_, trustForwarder_) {}

    // ========================================================================================================
    //                                          Buying related functions
    // ========================================================================================================
    function _buy(uint256 boxId_) internal {
        IBlindBox blindBox = BLIND_BOX;
        if (blindBox.getStatus(boxId_) != BoxStatus.Selling) revert InvalidStatus();
        address sender = _msgSender();
        bytes32 userId = USER_MANAGER.getUserId(sender);

        uint256 payAmount = blindBox.getPrice(boxId_);

        blindBox.setStatus(boxId_, BoxStatus.Paid);

        _boxExchangeData[boxId_]._buyerId = userId;
        _setRefundRequestDeadline(boxId_, block.timestamp);
        FUND_MANAGER.payOrderAmount(boxId_, sender, payAmount, userId);

        emit BoxPurchased(boxId_, userId);

    }

    /**
     * @notice Bid function, the bidder needs to pay a higher price to get the bid资格
     * @param boxId_ Box ID
     */
    function _bidPrice(uint256 boxId_) internal returns (uint256) {
        IBlindBox BlindBox = BLIND_BOX;
        (BoxStatus status, uint256 price, ) = BlindBox.getBasicData(boxId_);

        // canBid?
        if (status != BoxStatus.Auctioning) revert InvalidStatus();

        uint256 newPrice = (price * _bidIncrementRate) / 100; // If bidIncrementRate is 110, then it is 110%

        BlindBox.setBasicData(
            boxId_,
            newPrice,
            BoxStatus.Auctioning,
            block.timestamp + 7 days // NOTE bid refund deadline is 30 days + 7 days
        );

        return price;
    }

    function _bid(
        uint256 boxId_
    ) internal {
        address sender = _msgSender();
        bytes32 userId = USER_MANAGER.getUserId(sender);
        if (userId == _buyerIdOf(boxId_)) revert InvalidCaller();

        uint256 price = _bidPrice(boxId_);
        uint256 payAmount = _calcPayAmount(boxId_, userId, price);

        _boxExchangeData[boxId_]._buyerId = userId;
        _setRefundRequestDeadline(boxId_, block.timestamp + 7 days); // NOTE bid refund deadline is 30 days + 7 days
        FUND_MANAGER.payOrderAmount(boxId_, sender, payAmount, userId);

        emit BidPlaced(boxId_, userId);
    }

    /**
     * @notice Bid function, the bidder needs to pay a higher price to get the bid qualification
     * @param boxId_ Box ID
     * Need to check: deadline、status、buyer.
     * Bid will modify: buyer、price、deadline.
     * Bid also needs to calculate, and pay: payAmount
     */

    function _calcPayAmount(
        uint256 boxId_,
        bytes32 userId_,
        uint256 price_
    ) internal view returns (uint256) {
        uint256 balance = FUND_MANAGER.orderAmounts(
            boxId_,
            userId_
        );
        uint256 payAmount = price_ - balance;
        return payAmount;
    }

    // ========================================================================================================
    //                                           Refund function
    // ========================================================================================================

    /**
     * @notice Request refund function, after requesting refund, the box status becomes Refunding
     * Need to check: status、deadline.
     * Request refund will modify: status、arbitrationDeadline.
     */
    function _requestRefund(uint256 boxId_) internal {
        IBlindBox blindBox = BLIND_BOX;
        // canRequestRefund?
        if (blindBox.getStatus(boxId_) != BoxStatus.Paid) revert InvalidStatus();
        if (!_isInRequestRefundDeadline(boxId_)) revert DeadlineIsOver();
        // erc2771 - _msgSender() is the real caller
        bytes32 userId = USER_MANAGER.getUserId(_msgSender());
        if (userId != _buyerIdOf(boxId_)) revert NotBuyer();

        uint256 deadline = block.timestamp + _arbitrationPeriod;
        _boxExchangeData[boxId_]._arbitrationDeadline = deadline;

        blindBox.setStatus(boxId_, BoxStatus.Refunding);
        emit ArbitrationDeadineChanged(boxId_, deadline);
    }

    /**
     * @notice Cancel refund function, after canceling refund, the box status becomes Sold
     */
    function _cancelRefund(uint256 boxId_) internal {
        // erc2771 - _msgSender() is the real caller
        bytes32 userId = USER_MANAGER.getUserId(_msgSender());
        if (userId != _buyerIdOf(boxId_)) revert NotBuyer();

        IBlindBox blindBox = BLIND_BOX;
        if (blindBox.getStatus(boxId_) != BoxStatus.Refunding)
            revert InvalidStatus();

        blindBox.setStatus(boxId_, BoxStatus.Delaying);
        FUND_MANAGER.allocationRewards(boxId_);
    }

    /**
     * @notice Agree refund function, after agreeing refund, the box status becomes Sold
     * Need to check: status、deadline.
     * Agree refund will modify: status、arbitrationDeadline.
     * Agree refund also needs to set the status of BLIND_BOX to Published
     */
    function _agreeRefund(uint256 boxId_) internal {
        IBlindBox blindBox = BLIND_BOX;

        // canAgree?
        if (blindBox.getStatus(boxId_) != BoxStatus.Refunding)
            revert InvalidStatus();

        if (_isInArbitrationDeadline(boxId_)) {
            // erc2771 - _msgSender() is the real caller
            address sender = _msgSender();
            // Check role: minter、DAO
            bytes32 userId = USER_MANAGER.getUserId(sender);
            if (
                userId != blindBox.minterIdOf(boxId_) &&
                sender != ADDR_MANAGER.getMainContract(Main.Dao) // The dao must be a contract, so need not use _msgSender()
            ) {
                revert InvalidCaller();
            }
        }
        // If it exceeds the deadline, then it means anyone can call this function.
        _boxExchangeData[boxId_]._refundPermit = true;
        blindBox.setStatus(boxId_, BoxStatus.Published);
        emit RefundPermitChanged(boxId_, true);

    }

    /**
     * @notice Refuse refund function, after refusing refund, the box status becomes Published!
     */
    function _refuseRefund(uint256 boxId_) internal {
        IBlindBox blindBox = BLIND_BOX;

        if (_msgSender() != ADDR_MANAGER.getMainContract(Main.Dao)) revert NotDAO();
        // canRefuse?
        if (blindBox.getStatus(boxId_) != BoxStatus.Refunding)
            revert InvalidStatus();
        // According to whether it is within the review deadline, determine.
        if (_isInArbitrationDeadline(boxId_)) {
            FUND_MANAGER.allocationRewards(boxId_);
        } else {
            _boxExchangeData[boxId_]._refundPermit = true;
            emit RefundPermitChanged(boxId_, true);
        }
        blindBox.setStatus(boxId_, BoxStatus.Published);
    }

    // =========================================================================================================
    //                                           finalize related functions
    // ========================================================================================================

    /**
     * @notice Complete order function, after completing order, the box status becomes Sold
     * Need to check: refundPermit.
     * Complete order will modify: status、completer.
     * Complete order also needs to set the status of BLIND_BOX to Delaying
     * Complete order also needs to set refundRequestDeadline.
     */
    function _completeOrder(uint256 boxId_) internal {
        // _checkStatus(boxId_, BoxStatus.Paid);
        IBlindBox blindBox = BLIND_BOX;
        // canComplete?
        if (blindBox.getStatus(boxId_) != BoxStatus.Paid) revert InvalidStatus();
        if (_refundPermit(boxId_)) revert RefundPermitTrue();

        // erc2771
        address sender = _msgSender();
        bytes32 userId = USER_MANAGER.getUserId(sender);

        if (userId != _buyerIdOf(boxId_)) {
            if (_isInRequestRefundDeadline(boxId_)) revert DeadlineNotOver();
        }
        if (userId != blindBox.minterIdOf(boxId_)) {
            _boxExchangeData[boxId_]._completerId = userId;
            emit CompleterAssigned(boxId_, userId);
        }
        blindBox.setStatus(boxId_, BoxStatus.Delaying);
        FUND_MANAGER.allocationRewards(boxId_);
    }

}

contracts/BlindBox.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later

pragma solidity ^0.8.24;

import {BlindBox03} from "./base/BlindBox03.sol";
import {IBlindBox} from "@interfaces/sapphire/IBlindBox.sol";
import {BoxStatus} from "@interfaces/base/BoxStatus.sol";
import {Main} from "@interfaces/base/IContracts.sol";

/**
 *  @notice BlindBox contract
 *  Implement basic BlindBox functions, including mint, publish, blacklist, etc.
 *  Also includes important transaction-related functions, including setPrice, setDeadline, addDeadline, setStatus
 *  @dev Inherits IBlindBox interface to ensure consistency between interface and implementation
 */

contract BlindBox is BlindBox03, IBlindBox {
    // ==================================================================================================
    constructor(
        address addrManager_,
        address trustedForwarder_,
        bytes memory pers_
    ) BlindBox03(addrManager_, trustedForwarder_, pers_) {}

    function setContracts() external onlyAdmin {
        _setContracts();
    }

    // ==========================================================================================================
    //                                                 mint Functions
    // ==========================================================================================================

    function create(
        string calldata boxInfoCID_,
        bytes calldata key_,
        uint256 price_
    ) external returns (uint256) {
        return _create(boxInfoCID_, key_, price_);
    }

    function createAndPublish(
        string calldata boxInfoCID_
    ) external returns (uint256) {
        return _createAndPublish(boxInfoCID_);
    }

    //==================================================================================================
    //                                      Setter Functions
    //==================================================================================================

    function setPrice(
        uint256 boxId_,
        uint256 price_
    ) external onlyProjectContract {
        _setPrice(boxId_, price_);
    }

    function addDeadline(
        uint256 boxId_,
        uint256 seconds_
    ) external onlyProjectContract {
        _addDeadline(boxId_, seconds_);
    }

    function setStatus(
        uint256 boxId_,
        BoxStatus status_
    ) external onlyProjectContract {
        _setStatus(boxId_, status_);
    }

    function setBasicData(
        uint256 boxId_,
        uint256 price_,
        BoxStatus status_,
        uint256 deadline_
    ) external onlyProjectContract {
        _setPrice(boxId_, price_);
        _setStatus(boxId_, status_);
        _setDeadline(boxId_, deadline_);
    }

    // ==========================================================================================================
    //                                                delay function
    // ==========================================================================================================
    function extendDeadline(uint256 boxId_, uint256 time_) external {
        _extendDeadline(boxId_, time_);
    }

    // Safe payment, NFT must not be public and invalid
    function delay(uint256 boxId_) external {
        _delay(boxId_);
    }

    // ==========================================================================================================
    //                                                 public Functions
    // ==========================================================================================================

    function publishByMinter(uint256 boxId_) external {
        _checkMinter(boxId_);
        _isStatus(boxId_, BoxStatus.Storing);
        _setStatus(boxId_, BoxStatus.Published);
    }

    function publishByBuyer(uint256 boxId_) external {
        _checkBuyer(boxId_);
        _isStatus(boxId_, BoxStatus.Delaying);
        _setStatus(boxId_, BoxStatus.Published);
    }

    // ==========================================================================================================
    //                                                getter Functions
    // ==========================================================================================================

    function getStatus(uint256 boxId_) external view returns (BoxStatus) {
        return _getStatus(boxId_);
    }

    function getPrice(uint256 boxId_) external view returns (uint256) {
        return _basicData[boxId_]._price;
    }

    function getDeadline(uint256 boxId_) external view returns (uint256) {
        return _basicData[boxId_]._deadline;
    }

    // ==========================================================================================================
    /**
     * @dev Get public data of a box
     * @param boxId_ The ID of the box
     * @return status The status of the box
     * @return price The price of the box
     * @return deadline The deadline of the box
     * Everyone can call this function
     */
    function getBasicData(
        uint256 boxId_
    ) external view returns (BoxStatus, uint256, uint256) {
        BoxStatus status = _getStatus(boxId_);
        return (
            status,
            _basicData[boxId_]._price,
            _basicData[boxId_]._deadline
        );
    }

    function getSecretData(
        uint256 boxId_,
        bytes memory siweToken_
    ) external view returns (bytes memory) {
        return _getSecretData(boxId_, siweToken_);
    }

    // ==========================================================================================================

    function minterIdOf(
        uint256 boxId_
    ) external view returns (bytes32) {
        return _minterIdOf(boxId_);
    }

    // ==========================================================================================================
    function addToBlacklist(uint256 boxId_) external onlyDAO {
        _addToBlacklist(boxId_);
    }

    function isInBlacklist(uint256 boxId_) public view returns (bool) {
        return _basicData[boxId_]._status == BoxStatus.Blacklisted;
    }
}

contracts/Exchange.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later
// OpenZeppelin Contracts (last updated v5.0.0) (token/ERC721/ERC721.sol)

pragma solidity ^0.8.24;

import {IBlindBox} from "@interfaces/eth/IBlindBox.sol";
import {BoxStatus} from "@interfaces/base/BoxStatus.sol";
import {IExchange} from "@interfaces/IExchange.sol";
import {Exchange03} from "./base/Exchange03.sol";
import {Main} from "@interfaces/base/IContracts.sol";

/**
 *  @notice Exchange contract
 *  Implement basic BlindBox trading functions, including Selling, Auctioning, Paid, Refunding, Completed
 *  @dev Inherits IExchange interface to ensure consistency between interface and implementation
 */

contract Exchange is Exchange03, IExchange {
    // ========================================================================================================

    constructor(address addrManager_, address trustForwarder_) Exchange03(addrManager_, trustForwarder_) {}

    // ==========================================================================================================

    /**
     * @notice Set contract addresses
     * @dev Get and set related contract addresses from AddressManager
     */
    function setContracts() external onlyAdmin{
        _setContracts();
    }

    // ========================================================================================================
    //                                          Listing related functions
    // ========================================================================================================

    function sell(
        uint256 boxId_,
        address acceptedToken_,
        uint256 price_
    ) external {
        // NOTE: 365----15
        _setBoxListedArgs(
            boxId_,
            acceptedToken_,
            price_,
            BoxStatus.Selling,
            15 days
        );
    }

    function auction(
        uint256 boxId_,
        address acceptedToken_,
        uint256 price_
    ) external {
        // NOTE: 30 days----7 days
        _setBoxListedArgs(
            boxId_,
            acceptedToken_,
            price_,
            BoxStatus.Auctioning,
            7 days
        );
    }
    // ========================================================================================================
    //                                          Buying related functions
    // ========================================================================================================

    function buy(
        uint256 boxId_
    ) external {
        _buy(boxId_);
    }

    function bid(
        uint256 boxId_
    ) external {
        _bid(boxId_);
    }

    function calcPayAmount(
        uint256 boxId_,
        bytes32 userId_
    ) public view returns (uint256) {

        uint256 price = BLIND_BOX.getPrice(boxId_);
        return _calcPayAmount(boxId_, userId_, price);
    }

    // ========================================================================================================
    //                                           Refund function
    // ========================================================================================================

    function setRefundPermitTrue(
        uint256 boxId_
    ) external onlyProjectContract {
        _setRefundPermitTrue(boxId_);
    }

    function requestRefund(uint256 boxId_) external {
        _requestRefund(boxId_);
    }

    /**
     * @notice Cancel refund function, after canceling refund, the box status becomes Sold
     */
    function cancelRefund(uint256 boxId_) external {
        _cancelRefund(boxId_);
    }

    function agreeRefund(uint256 boxId_) external {
        _agreeRefund(boxId_);
    }

    /**
     * @notice Refuse refund function, after refusing refund, the box status becomes Published!
     */
    function refuseRefund(uint256 boxId_) external {
        _refuseRefund(boxId_);
    }

    function completeOrder(uint256 boxId_) external {
        _completeOrder(boxId_);
    }

    // ========================================================================================================
    //                                           Getter function
    // ========================================================================================================

    /**
     * @notice Get buyer address
     * @param boxId_ Box ID
     * @return Buyer address
     */
    function buyerIdOf(uint256 boxId_) external view returns (bytes32) {
        return _buyerIdOf(boxId_);
    }

    function sellerIdOf(uint256 boxId_) external view returns (bytes32) {
        return _sellerIdOf(boxId_);
    }

    function completerIdOf(uint256 boxId_) external view returns (bytes32) {
        return _completerIdOf(boxId_);
    }

    // ===========================
    function acceptedToken(uint256 boxId_) external view returns (address) {
        return _acceptedToken(boxId_);
    }

    // ===========================

    function refundPermit(uint256 boxId_) external view returns (bool) {
        return _refundPermit(boxId_);
    }

    function refundRequestDeadline(
        uint256 boxId_
    ) external view returns (uint256) {
        return _refundRequestDeadline(boxId_);
    }

    function arbitrationDeadline(
        uint256 boxId_
    ) external view returns (uint256) {
        return _arbitrationDeadline(boxId_);
    }

    // ==================== testnet only ===============

    // function isInRequestRefundDeadline(
    //     uint256 boxId_
    // ) external view returns (bool) {
    //     return _isInRequestRefundDeadline(boxId_);
    // }

    // function isInArbitrationDeadline(uint256 boxId_) external view returns (bool) {
    //     return _isInArbitrationDeadline(boxId_);
    // }

}

contracts/modifier/Modifier.sol.content:
// SPDX-License-Identifier: GPL-2.0-or-later

pragma solidity ^0.8.24;

import {IAddressManager} from "@interfaces/IAddressManager.sol";
import {Error} from "@interfaces/base/Error.sol";
import {Main} from "@interfaces/base/IContracts.sol";
/**
 * @title Modifier
 * @dev This contract is used to manage modifiers
 */

contract Modifier is Error {
    address internal ADMIN;
    IAddressManager internal ADDR_MANAGER;

    // =======================================================================================================
    constructor(address addrManager_) {
        ADMIN = msg.sender;
        ADDR_MANAGER = IAddressManager(addrManager_);
    }

    function setAddressManager(address addrManager_) external onlyAdmin {
        ADDR_MANAGER = IAddressManager(addrManager_);
    }

    function setAdmin(address admin_) external onlyAdmin {
        ADMIN = admin_;
    }

    function admin() external view returns (address) {
        return ADMIN;
    }

    // =====================================================================================

    modifier onlyAdmin() {
        if (msg.sender != ADMIN) revert NotAdmin();
        _;
    }

    modifier onlyDAO() {
        if (msg.sender != ADDR_MANAGER.getMainContract(Main.Dao)) revert NotDAO();
        _;
    }

    modifier onlyAdminDAO() {
        if (msg.sender != ADDR_MANAGER.getMainContract(Main.Dao) && msg.sender != ADMIN)
            revert NotAdminOrDAO();
        _;
    }

    // modifier onlyManager() {
    //     if (msg.sender != address(ADDR_MANAGER) && msg.sender != ADMIN) {
    //         revert InvalidCaller();
    //     }
    //     _;
    // }

    modifier onlyProjectContract() {
        if (!ADDR_MANAGER.isProjectContract(msg.sender)) {
            revert NotProjectCaller();
        }
        _;
    }
}

